      {section === "My goals" && <><div className="section-toolbar"><div className="toolbar-intro"><span className="count-badge">{data.goals.length}</span> goals in your journey <span className="toolbar-separator">·</span> {doneTasks.length} steps completed</div><button className="btn btn-primary" onClick={() => open("goal")}><Plus size={17}/> New goal</button></div><div className="idea-strip"><div className="idea-strip-icon"><WandSparkles size={21}/></div><div><b>Have an idea? Make it a plan.</b><p>Describe what you want to achieve and get actionable steps in seconds.</p></div><div className="strip-input"><input value={idea} onChange={e => setIdea(e.target.value)} onKeyDown={e => e.key === "Enter" && plan()} placeholder="I want to..."/><button disabled={busy || !idea.trim()} onClick={plan}>{busy ? <Loader2 className="spin" size={18}/> : <ArrowRight size={18}/>}</button></div></div><div className="goals-grid">{data.goals.map(g => { const list = data.tasks.filter(t => t.goalId === g.id); const pct = list.length ? Math.round(list.filter(t => t.completed).length/list.length*100) : 0; return <div className="goal-card" key={g.id}><div className="goal-card-top"><div className={`goal-card-icon ${g.color}`}>{g.category === "Creative" ? <PenLine size={21}/> : g.category === "Wellness" ? <Sparkles size={21}/> : g.category === "Business" ? <ArrowUpRight size={21}/> : <Target size={21}/>}</div><span className={`goal-status ${g.status === "completed" ? "done" : ""}`}>{g.status === "completed" ? "Completed" : "In progress"}</span></div><h3>{g.title}</h3><p>{g.description || "Your journey starts with a single step."}</p><div className="goal-meta"><span><Target size={14}/>{g.category}</span>{g.targetDate && <span><CalendarDays size={14}/>{fmt(g.targetDate + "T12:00:00")}</span>}</div><div className="goal-progress-label"><span>Progress</span><b>{pct}%</b></div><div className="progress-track"><div style={{width:`${pct}%`}}/></div><div className="goal-tasks">{list.slice(0,4).map(t => <div key={t.id}><button className={`task-check ${t.completed ? "checked" : ""}`} onClick={() => update("tasks",t.id,{completed:!t.completed})}>{t.completed && <Check size={12}/>}</button><span className={t.completed ? "is-done" : ""}>{t.title}</span><button className="row-delete" onClick={() => remove("tasks",t.id)} title="Delete task"><X size={13}/></button></div>)}{!list.length && <small>No steps yet. Add your first one below.</small>}</div><div className="goal-card-actions"><button onClick={() => { open("task"); setForm({goalId:g.id}); }}><Plus size={15}/> Add step</button><button onClick={() => update("goals",g.id,{status:g.status === "completed" ? "active" : "completed"})}>{g.status === "completed" ? <RotateCcw size={15}/> : <Check size={15}/>} {g.status === "completed" ? "Reopen" : "Finish"}</button><button title="Edit goal" onClick={() => open("goal",g as unknown as Record<string,unknown>)}><Pencil size={15}/></button><button title="Delete goal" onClick={() => remove("goals",g.id)}><Trash2 size={15}/></button></div></div>; })}{!data.goals.length && <div className="empty-large"><Target size={30}/><h3>Your next chapter starts here</h3><p>Create a goal or describe an idea above and we’ll help you find the first steps.</p><button className="btn btn-primary" onClick={() => open("goal")}><Plus size={16}/> Create a goal</button></div>}</div><div className="section-subhead"><div><h2>All your steps</h2><p>Small actions that move you forward.</p></div><button className="btn btn-outline" onClick={() => open("task")}><Plus size={16}/> Add task</button></div><div className="panel all-tasks">{data.tasks.map(t => <div className="full-task" key={t.id}><button className={`task-check ${t.completed ? "checked" : ""}`} onClick={() => update("tasks",t.id,{completed:!t.completed})}>{t.completed && <Check size={13}/>}</button><div><b className={t.completed ? "is-done" : ""}>{t.title}</b><small>{data.goals.find(g => g.id === t.goalId)?.title || "Personal task"}</small></div><span className={`priority priority-${t.priority}`}>{t.priority}</span><button className="icon-btn" onClick={() => open("task",t as unknown as Record<string,unknown>)}><Pencil size={15}/></button><button className="icon-btn danger-hover" onClick={() => remove("tasks",t.id)}><Trash2 size={15}/></button></div>)}{!data.tasks.length && <Empty icon={CheckCircle2} title="No tasks yet" text="Add a step to make your goals feel closer."/>}</div></>}
      {section === "AI companion" && <div className="chat-layout"><div className="chat-panel"><div className="chat-panel-head"><div className="assistant-avatar"><Sparkles size={22}/></div><div><b>Your Daywell companion</b><span><i/>{aiStatus?.mode === "own" ? `Your ${aiStatus.provider} model · ${aiStatus.model}` : aiStatus?.mode === "included" ? `Live AI · ${aiStatus.remaining} included requests left today` : "Guided mode · connect your own AI"}</span></div><button className="icon-btn" onClick={() => go("Settings")} title="AI settings"><Settings size={18}/></button></div><div className="chat-messages">{data.messages.length === 0 && <div className="chat-welcome"><div className="assistant-avatar"><Sparkles size={28}/></div><h3>What’s on your mind?</h3><p>Ask anything. We can make a plan, untangle a thought, or find the next step together.</p></div>}{data.messages.map(m => <div className={`message ${m.role === "user" ? "message-user" : "message-ai"}`} key={m.id}>{m.role !== "user" && <div className="message-avatar"><Sparkles size={16}/></div>}<div className="message-body"><div className="message-bubble">{m.content}</div><small>{m.role === "user" ? "You" : "Daywell"} · {new Date(m.createdAt).toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit"})}</small></div></div>)}{busy && <div className="message message-ai"><div className="message-avatar"><Sparkles size={16}/></div><div className="typing"><i/><i/><i/></div></div>}<div ref={chatEnd}/></div><div className="chat-bottom"><div className="chat-composer"><input placeholder="Ask me anything, or just say hello..." value={chatInput} onChange={e => setChatInput(e.target.value)} onKeyDown={e => e.key === "Enter" && chat()}/><button onClick={() => chat()} disabled={busy || !chatInput.trim()}><Send size={18}/></button></div><small>Here to help you think, plan, and grow. Your conversations are saved privately.</small></div></div><div className="chat-side"><div className="chat-side-card"><div className="side-spark"><Lightbulb size={21}/></div><h3>Not sure where to start?</h3><p>Pick a thought and let’s explore it together.</p>{["Help me plan my day", "I’m feeling a little stuck", "Give me writing inspiration", "How can I stay focused?"].map(x => <button key={x} onClick={() => chat(x)} disabled={busy}>{x}<ArrowUpRight size={15}/></button>)}</div><div className="chat-tip"><ShieldCheck size={19}/><div><b>Your space, your pace</b><p>Your own AI connection always takes priority over included AI. Manage your model in Settings.</p><button onClick={() => go("Settings")}>Connect a model <ArrowRight size={14}/></button></div></div></div></div>}
      {section === "Writing studio" && <><div className="studio-banner"><div><span><Sparkles size={15}/> YOUR CREATIVE SPACE</span><h2>Every story starts with a spark.</h2><p>From the first messy idea to the last polished line, create something entirely yours.</p></div><div className="studio-banner-art">✍</div></div><div className="section-subhead"><div><h2>Your writing projects <span className="soft-count">{data.projects.length}</span></h2><p>Pick up where inspiration left you.</p></div><button className="btn btn-primary" onClick={() => open("project")}><Plus size={17}/> New project</button></div><div className="project-grid">{data.projects.map(p => <button key={p.id} className={`project-card ${selectedProject === p.id ? "project-selected" : ""}`} onClick={() => { setSelectedProject(p.id); setWritingType(p.type); }}><div className="project-icon">{p.type === "Novel" ? <BookOpen size={23}/> : p.type === "Script" ? <Clapperboard size={23}/> : <FileText size={23}/>}</div><span className="project-type">{p.type.toUpperCase()} · {p.genre}</span><h3>{p.title}</h3><p>{p.premise || "A new story waiting to unfold."}</p><div className="project-footer"><span>Edited {fmt(p.updatedAt)}</span><ArrowUpRight size={17}/></div></button>)}<button className="project-add" onClick={() => open("project")}><div><Plus size={24}/></div><b>Start something new</b><span>Your next great idea belongs here.</span></button></div><div className="studio-workspace"><div className="workspace-head"><div><div className="panel-kicker">THE CREATIVE DESK</div><h2>{currentProject ? currentProject.title : "Create with AI"}</h2><p>{currentProject ? `Your ${currentProject.type.toLowerCase()} · ${currentProject.genre}` : "A writing partner for novels, stories, and scripts."}</p></div>{currentProject && <div className="workspace-actions"><button className="btn btn-outline" onClick={() => open("project", currentProject as unknown as Record<string,unknown>)}><Pencil size={15}/> Details</button><button className="icon-btn danger-hover" onClick={() => { remove("projects",currentProject.id); setSelectedProject(null); }}><Trash2 size={16}/></button></div>}</div><div className="studio-controls"><div className="field"><label>Format</label><select value={currentProject?.type || writingType} disabled={!!currentProject} onChange={e => setWritingType(e.target.value)}><option>Story</option><option>Novel</option><option>Script</option></select></div><div className="field"><label>What should we create?</label><select value={writingMode} onChange={e => setWritingMode(e.target.value)}><option value="draft">Opening draft</option><option value="outline">Story outline</option></select></div>{!currentProject && <><div className="field"><label>Title</label><input value={form.title || ""} onChange={e => setForm({...form,title:e.target.value})} placeholder="Your story title"/></div><div className="field"><label>Genre</label><input value={form.genre || ""} onChange={e => setForm({...form,genre:e.target.value})} placeholder="e.g. Fantasy"/></div></>}</div>{!currentProject && <div className="field premise-field"><label>Your premise or idea</label><textarea rows={2} value={form.premise || ""} onChange={e => setForm({...form,premise:e.target.value})} placeholder="A quiet bookshop owner discovers messages hidden in donated books..."/></div>}<div className="editor-top"><div><PenLine size={16}/> {currentProject ? "Your manuscript" : "A blank page, full of possibility"}</div><button className="btn btn-primary" onClick={generate} disabled={busy}>{busy ? <Loader2 className="spin" size={16}/> : <WandSparkles size={16}/>} {busy ? "Creating..." : currentProject ? "Generate more" : "Generate & save"}</button></div>{currentProject ? <textarea className="writing-editor" key={currentProject.id + currentProject.updatedAt} defaultValue={currentProject.content} placeholder="Start writing your story here..." onBlur={e => { if (e.target.value !== currentProject.content) update("projects", currentProject.id, {content:e.target.value}); }}/>: <div className="editor-empty"><PenLine size={25}/><p>Your words will find a home here.</p><span>Choose a project above or generate a new piece to begin.</span></div>}<div className="editor-foot"><span>{currentProject?.content.trim().split(/\s+/).filter(Boolean).length || 0} words</span><span>{currentProject ? "Changes save when you leave the editor" : "Create something wonderful"}</span></div></div></>}
